INSERT INTO youth_groups (name, parish, address, city, state, age_range, meeting_day, meeting_time, description, contact_person, contact_email, contact_phone, type, activities, requirements, members_count, max_capacity, created_by) VALUES
('St. Mary''s Youth Ministry', 'St. Mary''s Catholic Church', '123 Faith Street', 'Ahmedabad', 'Gujarat', '14-18', 'Sunday', '4:00 PM - 6:00 PM', 'A vibrant youth group focused on building a strong Catholic community through prayer, service, and fellowship. We meet every Sunday for faith sharing, games, and community service projects.', 'Fr. Thomas Abraham', 'youth@stmarys.org', '+91 98765 43210', ARRAY['Prayer', 'Service', 'Social'], ARRAY['Weekly faith sharing', 'Monthly service projects', 'Youth retreats', 'Sports activities'], ARRAY['Regular attendance', 'Parental consent for minors'], 45, 60, NULL),

('Sacred Heart Young Adults', 'Sacred Heart Cathedral', '456 Divine Avenue', 'Mumbai', 'Maharashtra', '18-25', 'Wednesday', '7:00 PM - 9:00 PM', 'A group for young adults seeking to deepen their faith through Bible study, adoration, and community outreach. Perfect for college students and young professionals.', 'Sarah Joseph', 'youngadults@sacredheart.org', '+91 87654 32109', ARRAY['Bible Study', 'Adoration', 'Outreach'], ARRAY['Weekly Bible study', 'Monthly adoration nights', 'Community outreach', 'Career guidance'], ARRAY['Age 18-25', 'Commitment to weekly meetings'], 32, 40, NULL),

('Holy Family Teen Ministry', 'Holy Family Church', '789 Blessing Road', 'Bangalore', 'Karnataka', '13-17', 'Saturday', '5:30 PM - 7:30 PM', 'A teen-focused ministry that combines faith formation with fun activities to help young Catholics grow in their faith journey. Music, drama, and creative arts are integral parts of our ministry.', 'Maria D''Souza', 'teens@holyfamily.org', '+91 76543 21098', ARRAY['Faith Formation', 'Social', 'Music'], ARRAY['Music ministry', 'Drama performances', 'Faith formation classes', 'Social events'], ARRAY['Age 13-17', 'Regular participation'], 28, 35, NULL),

('St. Joseph''s College Ministry', 'St. Joseph''s Church', '321 Grace Lane', 'Delhi', 'Delhi', '18-22', 'Friday', '6:00 PM - 8:00 PM', 'A college-focused ministry that helps students balance academic life with spiritual growth through study groups and retreats. We provide a supportive community for Catholic college students.', 'Fr. Michael Rodriguez', 'college@stjosephs.org', '+91 98765 12345', ARRAY['Study Groups', 'Retreats', 'Prayer'], ARRAY['Study support groups', 'Spiritual retreats', 'Prayer meetings', 'Academic guidance'], ARRAY['College enrollment', 'Catholic faith'], 38, 50, NULL),

('Our Lady of Mercy Youth', 'Our Lady of Mercy Parish', '654 Hope Street', 'Chennai', 'Tamil Nadu', '15-19', 'Thursday', '5:00 PM - 7:00 PM', 'A dynamic youth group that focuses on social justice, community service, and building lasting friendships in Christ. We actively engage in helping the less fortunate in our community.', 'Sister Catherine Francis', 'youth@ourladyofmercy.org', '+91 87654 98765', ARRAY['Social Justice', 'Service', 'Fellowship'], ARRAY['Community service', 'Social justice advocacy', 'Fellowship activities', 'Leadership training'], ARRAY['Age 15-19', 'Heart for service'], 42, 55, NULL);

